(* [comment removed for export] *)
Lemma rregions_disjoint_full : forall st rid1 r1 rid2 r2,
  rregions_wf st -> (s_regions st) !! rid1 = Some r1 -> (s_regions st) !! rid2 = Some r2 -> rid1 <> rid2 ->
