Lemma rmrep_meta_set_avail : forall st m g v,
  rmrep st m -> meta_slot st g -> 0 <= v < 2^32 ->
  rmrep (upd_meta g (m_set_avail v) st) (write_to_mem m (wa (conc st g + 24)) (le4 (wz v))).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40|30;|10;|500;}H$st;R+`7$m;R%~R!1+^G!1,^H|600;!1+D!1+^G!1,^H0$g;R'_H$v;R+4$~R!2'`8#4#3$~R!2'b>#5#3$~R!2+_1!2'<,^A#3!2'`@#3!2'a<!1,01!1,02!<'f:#7#6#5!1'f;#43#4#3#2#1$mr;R+d:!2,1!1+D+_=!2,J+_=!1,_>!1'_?!1'd?#1$mr;R+d:!2,1!1+2+_=!2'bD#8!2'f;#5#1!3,f6!3+8+`T33!3+8+`T3}L!2,1+`T3").
Qed.

Lemma rmrep_meta_set_freed : forall st m g v,
  rmrep st m -> meta_slot st g -> 0 <= v < 2^32 ->
  rmrep (upd_meta g (m_set_freed v) st) (write_to_mem m (wa (conc st g + 28)) (le4 (wz v))).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50|30;|10;|500;}L}H$st;R+`7$m;R%~R!1+^G!1,^H|600;!1+D!1+^G!1,^H0$g;R'_H$v;R+4$~R!2'`8#4#3$~R!2'b>#5#3$~R!2+_1!2'<,^A#3!2'`@#3!2'a<!1,01!1,02!<'f:#7#6#5!1'f<#43#4#3#2#1$mr;R+d:!2,1!1+D+_=!2,J+_=!1,_>!1'_?!1'd@#1$mr;R+d:!2,1!1+2+_=!2'bD#8!2'f<#5#1!3,f4!3+8+`T34!3+8+`T33!2,1+`T3").
Qed.


Lemma rmrep_set_active : forall st m sc v,
